GimCorpus.put(438,0,[[2,6,"שחטו למולים וזרק הדם לשם מולים. א\"א הא דלא כהלכתא דרב אשי דהוא בתרא קא פסיק מקצת ערלה לא פסלה ל\"ש בשחיטה ל\"ש בזריקה:",1,0],[2,13,"מי שחציו עבד עד משל עצמו. א\"א הא דלא כהלכתא דמשנה אחרונה אוכל משל עצמו:",1,0],[4,1,"הרי זה משובח ויביא פסח שני. א\"א אין כאן שבח שאם היה פטור אינו יכול להביא פסחו נדבה על תנאי שלמים:",1,0],[4,6,"מי שאבד פסחו עד והשני יקרב. א\"א זה שיבוש אלא ירעה עד שיסתאב ויביא בדמיו שלמים:",1,0],[5,2,"מי ששגג או נאנס ולא הקריב בראשון אם הזיד. א\"א שנה זה במשנתו כרבי. ור' נתן ור' חנינא בן עקביא פליגי עליה:",1,0],[5,2,"אע\"פ שהזיד בשני. א\"א עכשיו סותר את דבריו ומאי שנא טמא ודרך רחוקה והזיד בשני משוגג או נאנס בראשון והזיד בשני:",2,0],[5,5,"וכן טבילת אמהותיו. א\"א בתוספתא דפסחים בדברים שבין פסח מצרים לפסח דורות:",1,0],[5,9,"הלך ולא הגיע. א\"א אינו תופס דרך הגמרא:",1,0],[6,2,"טמא מת שחל שביעי עד אלא נדחה לפסח שני. א\"א אין דרך הלכה הולכת כן שהרי רב שאמר אין שוחטין וזורקין על טמא שרץ מכאן למד ואיהו ס\"ל שוחטין וזורקין על טבול יום וא\"כ זה טבול יום ורחמנא דחייה אלא האי קרא בשלא טבל ולא הזה דהיינו טמא שרץ ומעשה כי הוה הכי הוה ששחטו וזרקו עליהם קודם טבילה והזייה סברו שיעלה להן ולא שאלו אלא אחר זמן שחיטה ונדחו והכתוב מעיד כן שאמרו אנחנו טמאים לנפש אדם ואם לאחר טבילה והזייה מאי טומאה הויא בהו:",1,0],[6,2,"שהנזיר מגלח עליהם. א\"א לא מצאתי לזה שורש אף אם סברת עצמו הוא כיון שאילו אכל קדש בטומאה זו אין חייבין עליה כרת ולא קרבן אם הזה וטבל דין הוא שלא ידחה מפסחו:",2,0],[6,6,"ידחה ליום ארבעה עשר ומזין עליו. א\"א כל זה שיבוש שאם בא שביעי שלו בשבת הכל הפסיד שאין מזין לעולם אלא שלישי ושביעי שיהא השביעי חמישי לשלישי אלא שאין קפידא שיהיה שלישי ושביעי לפרישתו מן המת. ומה שאמר שאין שוחטין עליו אפילו לאחר טבילה והזייה כבר כתבנו מה שנראה לנו:",1,0],[6,6,"והלא איסור הזייה וכו' עד אינו זמן הקרבן. א\"א זה המפרש שפירש טעם להזאה וערל למה העמידו דבריהם במקום כרת לא עמד טעמו בו כי יום ארבעה עשר הוא זמן שחיטת הפסח וזריקתו והם לעונש הכרת עצמו והערל אם יטבול ביומו מה בכך ולמה נמנע אותו מלאכול ועוד דב\"ה אמרי אפילו ערל שמל ששה ימים קודם הפסח קאמרינן שלא יטבול ומצריכין אותו הזייה ג' וז' והרי נרפא מן המכה אם לא הזה ושנה וטבל והזה לא יאכל. ועוד לדבריו מצורע למה לא העמידו דבריהם והרי הוא בהזייה אבל הטעם לכולן שהשבות שיכול לבא לידי איסור כרת בו העמידו דבריהם במקום כרת דהאי כרת והאי כרת והיינו ערל עכו\"ם כמו שאמרו גזירה שמא יטמא במת לשנה הבאה וכו' והזאה נמי שמא יטלנה בידו וכו' וכן איזמל אבל אונן ובית הפרס שנידש ומצורע לבהונות אין כאן גזירה לפיכך לא העמידו:",2,0],[6,7,"ביום הקרבן שהוא יום י\"ד. א\"א כאן סותר מ\"ש למעלה שהוא עושה בכאן יום י\"ד זמן הקרבן ולפי דבריו היה לו לומר כאן ליל ט\"ו שהוא זמן אכילתו:",1,0],[6,13,"אבל אם נטמא בטומאת התהום. א\"א לא נראה מן הגמרא דנזיר אלא אפילו בשביעי עד שלא טבל והזה סותר אבל משטבל והזה שמשא ממילא ערבא ונזיר עד שלא גילח נמי סותר הואיל ומחוסר מעשה:",1,0],[8,9,"אין צולין את הפסח וכו'. א\"א והוא שלא יגע בכלי שהרי אמרו נגע בחרסו של תנור יקלוף את מקומו:",1,0],[9,6,"בני חבורה שנכנסו. א\"א סבב פני כל השמועה לענין אחר שאין הדעת מתיישב עליו ואין השכל מסכים עמו שאין זה הענין מתפרש אלא בחבורה שעושין סבולת ושוכרין להם שמש להשקותם ולסדר להם שולחנם ומאכלם ובא רב הונא לומר שאם שלשה מהם רוצים להתחיל יכנס השמש עמהם ויסדר לפניהם וישמש אותם ולא יאמר לא אזקק להכנס עד שתהיו כלכם אלא כיון שהוא זמן הסעודה והוא הרגיש בהם שאינן ממתינין עד שיהיו כולם אבל יש שממהר יותר מחבירו הילכך יש לו להכנס עם השלשה הראשונים ולשמשם אבל פחות משלשה לא שאינם ראויים לזימון ובטלה דעתם אצל כל אדם אבל אחר אכילה אם ימשך אחד או שנים באכילה ושתייה יותר משאר החבורה יש לו להמתין להם ולשמשם שהמנהג כן הוא יש מאריך ויש מקצר וזו החבורה בין שהן אוכלין מן האמצע בין שהם אוכלין בפ\"ע אמר רבינא ואלו המתאחרים אם הם פחות משלשה נותנין לו יותר על שכרו ולית הלכתא כוותיה וזה הענין הפשוט בשמועה זו ולא לענין פסח שיראה כשתי חבורות שלש וארבע גם כל מ\"ש בסוף אין בו טעם:",1,0],[9,7,"המאכיל כזית מן הפסח וגו' עד תושב ושכיר לא יאכל בו. א\"א ואפילו לישראל שאינו ממונה עמו אע\"פ שהוא תושבו או שכירו ולכך בא מדרשו ואין צורך לגר תושב שהוא ערל:",1,0],[10,6,"פסח שהוא נא וכו' עד שבר עצם האליה. א\"א בכלן תפס כרבנן ובאליה תפס כרבי:",1,0],[10,8,"הסחוסים וכו' עד שעצמותיו רכין לא יאכל אותן. א\"א מה נשתנו סברותיו בכמה מקומות ומעולם לא עלה על דעת מפרש שבאה זו המשנה על איסור שבירת העצם שאם כן היה לו לומר כל שאינו נאכל בשור הגדול לא יאכל בגדי הרך אבל באה על חיוב אכילה שהוא בבל תותירו:",1,0],[10,11,"כשאדם אוכל את הפסח וכו' עד העצמות והקרומות. א\"א בחיי ראשי אין איסור גדול מזה שיצלה הפסח עם גיד הנשה ועם שמנו ועם תרבא דתותי מתנא ועם קרומות שבראש ואם אזכה ואוכל פסח ויביא לפני כזה הייתי חובטו בקרקע לפניו:",1,0]]);
